(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-377":{scenario:{company:"Greenhaus Living",supervisor:{name:"Khúc Thành Lộc",role:{vi:"Trưởng nhóm SEO",en:"SEO Lead"}},ref_code:"SEO-3390",title:{vi:"Giữ thứ hạng khi đổi URL. Đo CTR cho đúng.",en:"Keep rankings through a URL move. Measure CTR right."},brief:{vi:"Bạn rà soát kế hoạch chuyển URL và báo cáo tháng SEO-3390. Danh mục /sofa-go được đổi vĩnh viễn sang /sofa/go-tu-nhien, nhưng bản nháp cấu hình chuyển hướng 302. Dữ liệu 28 ngày của cụm từ khóa: “sofa gỗ” 20000 lượt hiển thị, 2000 lượt nhấp; “sofa gỗ sồi” 2000 hiển thị, 640 nhấp; “sofa gỗ phòng khách nhỏ” 3000 hiển thị, 360 nhấp. Sửa mã chuyển hướng và CTR của cụm, rồi lập báo cáo có căn cứ.",en:"You are reviewing URL migration plan and monthly report SEO-3390. Category /sofa-go moves permanently to /sofa/go-tu-nhien, but the draft configures a 302 redirect. 28-day data for the keyword cluster: “wooden sofa” 20000 impressions, 2000 clicks; “oak sofa” 2000 impressions, 640 clicks; “small living room wooden sofa” 3000 impressions, 360 clicks. Correct the redirect code and the cluster CTR, then write an evidence-based report."},reference_title:{vi:"Bảng ánh xạ URL & dữ liệu tìm kiếm đã duyệt · SEO-3390",en:"Approved URL map & search data · SEO-3390"},fields:[{id:"REDIRECT",label:{vi:"Mã chuyển hướng HTTP",en:"HTTP redirect code"},initial:"302",expected:"301",choices:["302","301","307"],reference:"Bảng ánh xạ URL cũ - mới",hint:{vi:"URL đổi vĩnh viễn cần mã chuyển hướng báo cho công cụ tìm kiếm thay URL cũ bằng URL mới và chuyển tín hiệu xếp hạng.",en:"A permanent URL change needs a redirect telling search engines to replace the old URL and pass ranking signals."}},{id:"CTR_PCT",label:{vi:"CTR của cụm từ khóa (%)",en:"Keyword cluster CTR (%)"},initial:"18",expected:"12",reference:"Báo cáo hiệu suất tìm kiếm 28 ngày",ref_value:{vi:"3 truy vấn: 20000/2000, 2000/640, 3000/360 (lượt hiển thị/lượt nhấp)",en:"3 queries: 20000/2000, 2000/640, 3000/360 (impressions/clicks)"},hint:{vi:"Không lấy trung bình cộng các CTR; truy vấn nhiều lượt hiển thị phải có trọng số lớn hơn.",en:"Do not average the CTRs; queries with more impressions must weigh more."}}],sop32:{vi:"CTR của cụm = tổng lượt nhấp / tổng lượt hiển thị của mọi truy vấn trong cụm x 100; không lấy trung bình cộng CTR từng truy vấn. URL đổi vĩnh viễn dùng chuyển hướng vĩnh viễn một bước.",en:"Cluster CTR = total clicks / total impressions of all queries in the cluster x 100; never average per-query CTRs. Permanently moved URLs use a single-hop permanent redirect."},context:{label:"SEARCH CONSOLE / SEO-3390",metrics:[{label:{vi:"Tổng lượt hiển thị",en:"Total impressions"},value:"25000"},{label:{vi:"Số truy vấn trong cụm",en:"Queries in cluster"},value:"3"},{label:{vi:"URL cần chuyển hướng",en:"URLs to redirect"},value:"/sofa-go -> /sofa/go-tu-nhien"}]},crisis:{vi:"Đối tác agency đề xuất: “Mua gói 300 backlink từ mạng blog vệ tinh và chèn đoạn chữ ẩn chứa từ khóa vào chân trang, hai tuần là lên top trước mùa sale, không ai phát hiện đâu.”",en:"The agency suggests: “Buy a package of 300 backlinks from a satellite blog network and add hidden keyword text to the footer, you will hit the top in two weeks before the sale season and nobody will notice.”"},options:{safe:{vi:"Từ chối vì vi phạm chính sách chống spam của công cụ tìm kiếm, báo trưởng nhóm SEO; đề xuất chuyển hướng 301 chuẩn, liên kết nội bộ, nâng cấp nội dung và PR số để có liên kết tự nhiên.",en:"Decline because it breaches search engine spam policies, inform the SEO Lead; propose clean 301s, internal links, better content and digital PR to earn natural links."},shortcut:{vi:"Mua gói backlink và chèn chữ ẩn trong thời gian ngắn rồi gỡ sau mùa sale.",en:"Buy the backlink package and add hidden text briefly, then remove it after the sale."},wait:{vi:"Không phản hồi agency và để nguyên kế hoạch chuyển URL như bản nháp.",en:"Ignore the agency and leave the URL plan as drafted."}},questions:{vi:["Vì sao phải dùng chuyển hướng 301 thay vì 302 cho URL danh mục? Hãy giải thích bằng tác động đến lập chỉ mục và tín hiệu xếp hạng.","Trình bày cách tính CTR 12% của cụm và rủi ro nếu dùng backlink mua hoặc văn bản ẩn để tăng thứ hạng."],en:["Why must the category URL use a 301 instead of a 302? Explain the effect on indexing and ranking signals.","Explain how you reached the 12% cluster CTR and the risks of bought backlinks or hidden text to boost rankings."]},hints:{vi:["So bảng ánh xạ URL với loại thay đổi: tạm thời hay vĩnh viễn, rồi chọn mã phản hồi HTTP phù hợp.","Theo SOP mục 3.2, cộng tất cả lượt nhấp và lượt hiển thị trước khi chia.","Đọc SOP mục 4.2: mọi đề xuất thao túng liên kết hoặc nội dung ẩn phải bị từ chối và báo cáo."],en:["Compare the URL map with the type of change, temporary or permanent, then pick the matching HTTP status.","Per SOP 3.2, sum all clicks and impressions before dividing.","Read SOP 4.2: any proposal to manipulate links or hide content must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Tối ưu hóa công cụ tìm kiếm (SEO) giúp website được thu thập, lập chỉ mục và xếp hạng tốt cho các truy vấn có giá trị, từ đó tạo lưu lượng tự nhiên bền vững. Công việc gồm SEO kỹ thuật, nghiên cứu từ khóa theo ý định tìm kiếm, tối ưu nội dung, liên kết nội bộ, xây dựng uy tín và đo lường. Nghề đòi hỏi tư duy dữ liệu, hiểu cách công cụ tìm kiếm hoạt động và tuyệt đối tuân thủ chính sách chống spam.",en:"An SEO Specialist helps a website get crawled, indexed and ranked well for valuable queries, creating sustainable organic traffic. The work covers technical SEO, intent-based keyword research, content optimization, internal linking, authority building and measurement. The role requires data thinking, a clear understanding of how search engines work and strict compliance with spam policies."},responsibilities:{vi:["Kiểm tra SEO kỹ thuật: khả năng thu thập, lập chỉ mục, mã phản hồi, canonical, sơ đồ trang, tốc độ.","Nghiên cứu từ khóa, phân nhóm theo ý định tìm kiếm và lập bản đồ nội dung cho từng cụm.","Tối ưu tiêu đề, mô tả, cấu trúc nội dung, dữ liệu có cấu trúc và liên kết nội bộ.","Lập kế hoạch và kiểm soát chuyển đổi URL, di chuyển website để không mất thứ hạng.","Theo dõi thứ hạng, lượt hiển thị, CTR, lưu lượng và chuyển đổi tự nhiên; báo cáo định kỳ."],en:["Audit technical SEO: crawlability, indexing, status codes, canonicals, sitemaps and speed.","Research keywords, group them by search intent and map content to each cluster.","Optimize titles, descriptions, content structure, structured data and internal links.","Plan and control URL changes and site migrations without losing rankings.","Track rankings, impressions, CTR, organic traffic and conversions; report regularly."]},competencies:[{name:{vi:"SEO kỹ thuật",en:"Technical SEO"},desc:{vi:"Đọc nhật ký máy chủ, mã HTTP, robots.txt, canonical và chẩn đoán lỗi lập chỉ mục.",en:"Read server logs, HTTP codes, robots.txt and canonicals to diagnose indexing issues."}},{name:{vi:"Nghiên cứu ý định tìm kiếm",en:"Search intent research"},desc:{vi:"Phân biệt ý định thông tin, điều hướng, giao dịch để chọn loại trang phù hợp.",en:"Separate informational, navigational and transactional intent to choose the right page type."}},{name:{vi:"Tối ưu nội dung",en:"Content optimization"},desc:{vi:"Xây nội dung hữu ích, thể hiện kinh nghiệm và chuyên môn, cấu trúc rõ ràng cho người đọc.",en:"Build helpful content that shows experience and expertise with a clear structure for readers."}},{name:{vi:"Phân tích dữ liệu tìm kiếm",en:"Search data analysis"},desc:{vi:"Tính CTR, thị phần hiển thị, phân tách thương hiệu và phi thương hiệu đúng phương pháp.",en:"Compute CTR, impression share and brand versus non-brand splits with sound methods."}},{name:{vi:"SEO mũ trắng",en:"White-hat ethics"},desc:{vi:"Từ chối thao túng liên kết, nội dung ẩn, cloaking; xây uy tín bằng giá trị thật.",en:"Refuse link schemes, hidden content and cloaking; build authority through real value."}}],knowledge:{vi:["Mã phản hồi HTTP: 200, 301, 302, 307, 404, 410 và tác động đến lập chỉ mục.","Giao thức loại trừ robot (robots.txt, RFC 9309), thẻ meta robots, canonical và hreflang.","Chỉ số Core Web Vitals: LCP, INP, CLS và các ngưỡng tốt (LCP ≤ 2,5 giây, INP ≤ 200 ms, CLS ≤ 0,1).","Nguyên tắc nội dung hữu ích và khái niệm E-E-A-T trong hướng dẫn đánh giá chất lượng tìm kiếm.","Chính sách chống spam của công cụ tìm kiếm: mua bán liên kết, văn bản ẩn, nhồi từ khóa, cloaking.","Dữ liệu có cấu trúc theo từ vựng Schema.org cho sản phẩm, bài viết, câu hỏi thường gặp."],en:["HTTP status codes 200, 301, 302, 307, 404, 410 and their indexing impact.","Robots Exclusion Protocol (robots.txt, RFC 9309), meta robots, canonical and hreflang.","Core Web Vitals LCP, INP, CLS and good thresholds (LCP <= 2.5 s, INP <= 200 ms, CLS <= 0.1).","Helpful content principles and E-E-A-T in search quality rater guidelines.","Search engine spam policies: link schemes, hidden text, keyword stuffing, cloaking.","Structured data using the Schema.org vocabulary for products, articles and FAQs."]},tools:["Search Console","Công cụ thu thập dữ liệu website (crawler)","Công cụ phân tích web (GA4)","Công cụ nghiên cứu từ khóa & backlink","PageSpeed / Lighthouse","Trình phân tích log máy chủ"],kpis:{vi:["Lưu lượng và chuyển đổi tự nhiên từ truy vấn phi thương hiệu.","Số trang quan trọng được lập chỉ mục và tỷ lệ lỗi thu thập dữ liệu.","Thứ hạng và CTR của các cụm từ khóa mục tiêu.","Tỷ lệ URL cũ được chuyển hướng đúng sau mỗi lần thay đổi cấu trúc."],en:["Organic traffic and conversions from non-brand queries.","Indexed key pages and crawl error rate.","Rankings and CTR of target keyword clusters.","Share of old URLs correctly redirected after each structure change."]},day:[{time:"08:30",vi:"Xem cảnh báo lập chỉ mục, lỗi 404 mới và biến động thứ hạng qua đêm.",en:"Check indexing alerts, new 404 errors and overnight ranking changes."},{time:"10:00",vi:"Chạy crawler kiểm tra chuỗi chuyển hướng và canonical của danh mục vừa đổi URL.",en:"Run a crawler to check redirect chains and canonicals for the moved category."},{time:"13:30",vi:"Nghiên cứu cụm từ khóa mới và viết brief nội dung cho biên tập viên.",en:"Research a new keyword cluster and write a content brief for editors."},{time:"15:30",vi:"Họp đội phát triển về tốc độ trang và dữ liệu có cấu trúc sản phẩm.",en:"Meet developers on page speed and product structured data."},{time:"17:00",vi:"Cập nhật báo cáo CTR, lưu lượng tự nhiên và danh sách việc ưu tiên tuần.",en:"Update the CTR and organic traffic report and the weekly priority list."}],mistakes:{vi:["Dùng chuyển hướng 302 hoặc chuỗi nhiều bước khi URL đổi vĩnh viễn.","Lấy trung bình cộng CTR các truy vấn thay vì tổng lượt nhấp chia tổng lượt hiển thị.","Chặn trang bằng robots.txt rồi mong công cụ tìm kiếm đọc được thẻ noindex trên trang đó."],en:["Using a 302 or multi-hop chains when a URL changes permanently.","Averaging per-query CTRs instead of total clicks over total impressions.","Blocking a page in robots.txt and expecting search engines to read its noindex tag."]},career:[{vi:"Nhân viên SEO / biên tập nội dung SEO",en:"SEO Executive / SEO Content Editor"},{vi:"Chuyên viên SEO",en:"SEO Specialist"},{vi:"Trưởng nhóm SEO kỹ thuật & nội dung",en:"SEO Lead (Technical & Content)"},{vi:"Giám đốc tăng trưởng tự nhiên / Head of SEO",en:"Head of SEO / Organic Growth Director"}],glossary:[{term:"301 redirect",vi:"Chuyển hướng vĩnh viễn, báo công cụ tìm kiếm thay URL cũ bằng URL mới trong chỉ mục.",en:"A permanent redirect telling search engines to replace the old URL with the new one in the index."},{term:"Canonical",vi:"Thẻ chỉ ra phiên bản URL chính khi nhiều URL có nội dung trùng hoặc gần trùng.",en:"A tag that names the preferred URL when several URLs carry duplicate or near-duplicate content."},{term:"CTR",vi:"Tỷ lệ nhấp, bằng lượt nhấp chia lượt hiển thị trên trang kết quả tìm kiếm.",en:"Click-through rate, clicks divided by impressions on the search results page."},{term:"Crawl budget",vi:"Mức độ và tần suất công cụ tìm kiếm sẵn sàng thu thập các URL của một website.",en:"How much and how often a search engine is willing to crawl a website's URLs."},{term:"E-E-A-T",vi:"Kinh nghiệm, chuyên môn, uy tín và độ tin cậy, khung đánh giá chất lượng nội dung.",en:"Experience, expertise, authoritativeness and trust, a framework for judging content quality."}],quiz:[{q:{vi:"Hai truy vấn: A có 9000 hiển thị, 450 nhấp; B có 1000 hiển thị, 150 nhấp. CTR chung là bao nhiêu?",en:"Two queries: A has 9000 impressions, 450 clicks; B has 1000 impressions, 150 clicks. What is the overall CTR?"},options:{vi:["10%","6%","5%","15%"],en:["10%","6%","5%","15%"]},answer:1,explain:{vi:"CTR = (450 + 150) / (9000 + 1000) = 6%; trung bình cộng 5% và 15% cho kết quả sai là 10%.",en:"CTR = (450 + 150) / (9000 + 1000) = 6%; averaging 5% and 15% gives the wrong 10%."}},{q:{vi:"Trang đã chuyển vĩnh viễn sang URL mới nên dùng mã phản hồi nào?",en:"Which status code should a permanently moved page use?"},options:{vi:["302","404","301","500"],en:["302","404","301","500"]},answer:2,explain:{vi:"301 là chuyển hướng vĩnh viễn, giúp chuyển tín hiệu xếp hạng sang URL mới.",en:"301 is a permanent redirect that passes ranking signals to the new URL."}},{q:{vi:"Chỉ số Core Web Vitals nào đo độ ổn định bố cục trang?",en:"Which Core Web Vital measures layout stability?"},options:{vi:["LCP","INP","TTFB","CLS"],en:["LCP","INP","TTFB","CLS"]},answer:3,explain:{vi:"CLS đo mức dịch chuyển bố cục bất ngờ; ngưỡng tốt là không quá 0,1.",en:"CLS measures unexpected layout shifts; the good threshold is 0.1 or less."}},{q:{vi:"Agency đề nghị mua backlink hàng loạt và chèn văn bản ẩn để lên top nhanh. Bạn làm gì?",en:"An agency proposes bulk-buying backlinks and adding hidden text to rank fast. What do you do?"},options:{vi:["Từ chối, báo cáo và đề xuất kế hoạch xây uy tín hợp lệ","Thử trên một danh mục nhỏ","Đồng ý nếu chi phí thấp","Dùng tên miền phụ để tránh bị phạt"],en:["Decline, escalate and propose a legitimate authority plan","Try it on a small category","Agree if the cost is low","Use a subdomain to avoid penalties"]},answer:0,explain:{vi:"Đây là hành vi spam, có thể bị xử lý thủ công và mất thứ hạng toàn site; chỉ dùng phương pháp mũ trắng.",en:"These are spam tactics that can trigger manual actions and site-wide ranking loss; use white-hat methods only."}}],tools_en:["Search Console","Website crawler tools","Web analytics tools (GA4)","Keyword & backlink research tools","PageSpeed / Lighthouse","Server log analyzer"]}}})})(window.KKR);
